import type { Session } from '@supabase/supabase-js';
import type { WorkspaceSupabaseClient } from './client';

export async function getSupabaseSession(client: WorkspaceSupabaseClient): Promise<Session | null> {
  const { data, error } = await client.auth.getSession();
  if (error) {
    throw error;
  }
  return data.session;
}

export async function getSupabaseAccessToken(
  client: WorkspaceSupabaseClient
): Promise<string | null> {
  const session = await getSupabaseSession(client);
  return session?.access_token ?? null;
}

import { useEffect, useState } from 'react';
import { X, Search, ArrowUpRight } from 'lucide-react';
import type { Product } from './types';
import { getProducts } from './types';

interface SearchOverlayProps {
  open: boolean;
  onClose: () => void;
}

const HOT_KEYWORDS = ['凉感T恤', '斜挎包', '防晒衣', '短裤', '滤镜'];

export default function SearchOverlay({ open, onClose }: SearchOverlayProps) {
  const [query, setQuery] = useState('');
  const products = getProducts();

  useEffect(() => {
    if (open) setQuery('');
  }, [open]);

  const results: Product[] =
    query.trim().length === 0
      ? products.slice(0, 4)
      : products.filter((p) => p.name.toLowerCase().includes(query.trim().toLowerCase()));

  return (
    <div
      className={`fixed inset-0 z-50 bg-surface-raised transition-opacity duration-200 ease-out ${
        open ? 'opacity-100' : 'opacity-0 pointer-events-none'
      }`}
      role="dialog"
      aria-label="搜索"
      aria-hidden={!open}
    >
      <div className="layout-safe pt-comfortable">
        {/* Search bar */}
        <div className="flex items-center gap-base border-b-2 border-text-primary pb-base">
          <Search className="size-6 shrink-0 text-text-primary" strokeWidth={2} aria-hidden="true" />
          <input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="搜索商品"
            aria-label="搜索商品"
            className="flex-1 min-w-0 bg-transparent text-h2 font-bold tracking-tight text-text-primary placeholder:text-text-secondary/50 focus:outline-none"
          />
          <button
            type="button"
            onClick={onClose}
            aria-label="关闭搜索"
            className="p-tight text-text-secondary hover:text-text-primary transition-colors duration-150"
          >
            <X className="size-6" strokeWidth={2} aria-hidden="true" />
          </button>
        </div>

        {/* Hot keywords */}
        <div className="mt-comfortable">
          <div className="text-[13px] font-semibold tracking-wider text-text-secondary uppercase">热门搜索</div>
          <div className="mt-base flex flex-wrap gap-tight">
            {HOT_KEYWORDS.map((kw) => (
              <button
                key={kw}
                type="button"
                onClick={() => setQuery(kw)}
                className="rounded-full border border-border-subtle px-comfortable py-tight text-sm text-text-primary transition-colors duration-150 hover:border-text-primary hover:bg-surface-base"
              >
                {kw}
              </button>
            ))}
          </div>
        </div>

        {/* Results */}
        <div className="mt-comfortable pb-section">
          <div className="text-[13px] font-semibold tracking-wider text-text-secondary uppercase">
            {query.trim() ? `搜索结果（${results.length}）` : '推荐商品'}
          </div>
          {results.length === 0 ? (
            <p className="mt-base text-text-secondary">未找到相关商品，请尝试其他关键词。</p>
          ) : (
            <ul className="mt-base divide-y divide-border-subtle">
              {results.map((p) => (
                <li key={p.slug}>
                  <button
                    type="button"
                    onClick={() => {
                      onClose();
                      window.App.transitionTo('product', { slug: p.slug });
                    }}
                    className="group flex w-full items-center gap-base py-base text-left"
                  >
                    <img
                      src={p.image}
                      alt={`YihuiCrew ${p.name}`}
                      className="w-16 aspect-[3/4] object-cover bg-surface-base shrink-0"
                      loading="lazy"
                    />
                    <div className="flex-1 min-w-0">
                      <div className="text-[13px] text-text-secondary">{p.brand}</div>
                      <div className="text-base font-semibold text-text-primary truncate">{p.name}</div>
                    </div>
                    <div className="text-sm font-medium tabular-nums text-text-primary">{p.price}</div>
                    <ArrowUpRight
                      className="size-4 text-text-secondary transition-transform duration-150 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 group-hover:text-brand-primary"
                      strokeWidth={2}
                      aria-hidden="true"
                    />
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}

