import { useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { useShop } from "../lib/state";
import { localized, unitPrice, formatMoney } from "../lib/types";
import type { Product, CartItem } from "./types";
import appearance from "./appearance.json";
import words from "./words.json";
export function useText() {
  const { lang } = useShop();
  return (text: string) =>
    lang === "zh" ? text : (words as Record<string, string>)[text] || text;
}
export function usePresentation() {
  const s = useShop(),
    navigate = useNavigate(),
    tr = useText();
  const products: Product[] = useMemo(
    () =>
      s.products.map((p) => {
        const look = appearance.products.find((x) => x.slug === p.slug);
        const model = look?.modelInfo || "";
        return {
          id: p.id,
          slug: p.slug,
          name: localized(p.name, s.lang),
          brand: "YihuiCrew",
          price: formatMoney(unitPrice(p, s.currency), s.currency, s.lang),
          priceValue: unitPrice(p, s.currency) / 100,
          category: p.category,
          isNew: p.is_new,
          inStock: p.stock > 0,
          colors: p.colors.map((c) => {
            const index = look?.colorNames?.indexOf(c.zh) ?? -1;
            return look?.colors?.[index] || "#808080";
          }),
          colorNames: p.colors.map((c) => localized(c, s.lang)),
          sizes: p.sizes,
          image: p.images[0] || "",
          image2: p.images[1] || p.images[0] || "",
          images: p.images,
          description: localized(p.description, s.lang),
          material: localized(p.material, s.lang),
          details: s.lang === "zh" ? look?.details || [] : [],
          modelInfo:
            s.lang === "zh"
              ? model
              : tr(model).replace(
                  /模特身高 (\d+)cm \/ 体重 (\d+)kg，穿着尺码 (.+)/,
                  "Model: $1 cm / $2 kg, wearing size $3",
                ),
        };
      }),
    [s.products, s.lang, s.currency],
  );
  const addItem = (item: CartItem) => {
    const p = products.find((p) => p.slug === item.slug);
    if (p?.inStock)
      s.add({
        product_id: p.id,
        color: Math.max(0, p.colorNames.indexOf(item.color)),
        size: item.size,
        quantity: item.qty,
      });
  };
  const go = (page: string, params?: Record<string, string>) =>
    navigate(
      page === "home"
        ? "/"
        : page === "product"
          ? `/products/${params?.slug}`
          : page === "blog"
            ? "/journal"
            : page === "admin"
              ? "/admin"
              : `/collections${params?.tab ? "?category=" + params.tab : ""}`,
    );
  const hero = {
    ...appearance.hero,
    tags: appearance.hero.tags.map(tr),
    subtitle: tr(appearance.hero.subtitle),
    primaryAction: tr(appearance.hero.primaryAction),
    secondaryAction: tr(appearance.hero.secondaryAction),
    tiles: appearance.hero.tiles.map((tile) => ({
      ...tile,
      layout: tile.layout as "tall" | "half-top" | "half-bottom",
      badge: tr(tile.badge),
    })),
  };
  const banners = Object.fromEntries(
    Object.entries(appearance.banners).map(([key, value]) => [
      key,
      {
        ...value,
        title: tr(value.title),
        subtitle: tr(value.subtitle),
        cta: tr(value.cta),
        eyebrow: "eyebrow" in value ? tr(value.eyebrow) : undefined,
      },
    ]),
  ) as {
    summer: import("./types").BannerBlock;
    electronics: import("./types").BannerBlock;
  };
  return {
    ...s,
    products,
    addItem,
    go,
    tr,
    hero,
    banners,
    featuredSlugs: appearance.featuredSlugs,
  };
}

